from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_transcript_log_flags_whitespace_and_skipped_lines():
    lines = ["", " \t\n", "  # comment,not a day,1", " a , 1 , 1 ", " b , -2 , 0 ", " c , 3 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,x", "a,1.5,0"])
def test_parse_transcript_log_error_counts_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", "  # comment", "a,1,1", bad_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    first = {"id": "a", "day": 5, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    same_day = {"id": "b", "day": 2, "flagged": True}
    earlier_day = {"id": "z", "day": 1, "flagged": None}
    assert dedupe_transcripts([first, same_day, last, earlier_day]) == [earlier_day, last, same_day]


def test_daily_flag_counts_inclusive_range_with_gaps_and_outside_events():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,3,", "f,5,1", "g,6,1"])
    assert daily_flag_counts(events, 2, 5) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 5, 2) == []
    assert daily_flag_counts([], 2, 3) == [0, 0]
"}

