def test_monitor_summary_pools_events_and_uses_calendar_days():
    groups = {
        "g": parse_transcript_log(["a,1,1", "b,3,1"]),
        "h": parse_transcript_log(["c,5,0"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary(groups, 0) == {"rate": 0.667, "recent": 0, "groups": 2}


def test_monitor_summary_without_transcripts():
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_orders_ties_by_name_and_excludes_empty_groups():
    groups = {
        "empty": [],
        "z": [{"flagged": True}],
        "a": [{"flagged": True}],
        "b": [{"flagged": None}],
    }
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 0) == []
